CREATE COLUMN TABLE "TEST_AP"."OCR1" ("OcrCode" NVARCHAR(8) NOT NULL , "PrcCode" NVARCHAR(8) NOT NULL , "PrcAmount" DECIMAL(21,6) CS_FIXED, "OcrTotal" DECIMAL(21,6) CS_FIXED, "Direct" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "ValidFrom" LONGDATE CS_LONGDATE DEFAULT '19000101' NOT NULL , "ValidTo" LONGDATE CS_LONGDATE, "logInstanc" INTEGER CS_INT, "UserSign2" SMALLINT CS_INT, "updateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("OcrCode", "PrcCode", "ValidFrom")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE INDEX "OCR1_PROF_ID" ON "TEST_AP"."OCR1" ( "PrcCode" ASC )